Original:
```typescript
export function bookValue(
  costCents: number,
  salvageCents: number,
  lifeYears: number,
  ageYears: number,
): number {
  const yearly = (costCents - salvageCents) / lifeYears;
  const used = Math.min(ageYears, lifeYears);
  return Math.round(costCents - yearly * used);
}

```

